const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the location and date
  const lon = -122.403124;
  const lat = 40.575441;
  const point = ee.Geometry.Point([lon, lat]);

  const targetDate = '2020-08-25';
  const startDate = '2020-08-24';
  const endDate = '2020-08-26';

  // Try MERRA-2 black carbon data (most direct source)
  let bc = ee.ImageCollection('COPERNICUS/S5P/NRTI')
    .select('BC_concentration')
    .filterBounds(point)
    .filterDate(startDate, endDate);

  let size = bc.size().getInfo();

  // Fallback: Try MODIS aerosol products combined with black carbon fraction
  if (size === 0) {
    bc = ee.ImageCollection('MODIS/061/MYD04_3K')
      .filterBounds(point)
      .filterDate(startDate, endDate);
    size = bc.size().getInfo();
  }

  // Fallback: Try GEOS-5 or standard aerosol data
  if (size === 0) {
    bc = ee.ImageCollection('NOAA/GOES/16/ABI')
      .filterBounds(point)
      .filterDate(startDate, endDate);
    size = bc.size().getInfo();
  }

  print("Collection size: " + size);

  if (size === 0) {
    print("No black carbon data found for date range 2020-08-24 to 2020-08-26");
    print("C1");
    return;
  }

  // Get first image from collection
  const img = bc.first();

  // List bands to identify the correct band
  const bandNames = img.bandNames().getInfo();
  print("Available bands: " + bandNames);

  // Select appropriate band (BC_concentration or similar)
  let bcBand = 'BC_concentration';
  if (!bandNames.includes('BC_concentration')) {
    bcBand = bandNames[0]; // Use first available
  }

  // Extract value at point
  const sample = img.sample(point, 1000).first();
  const bcValue = sample.get(bcBand).getInfo();

  print("Black carbon value (mg/m²): " + bcValue);

  // Validate result
  if (bcValue === null || bcValue === undefined || isNaN(bcValue)) {
    print("C3");
    return;
  }

  // Check if value > 12 mg/m²
  if (bcValue > 12) {
    print("Black carbon: " + bcValue.toFixed(2) + " mg/m² > 12 mg/m²");
    print("A");
  } else {
    print("Black carbon: " + bcValue.toFixed(2) + " mg/m² ≤ 12 mg/m²");
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
